-- ====================================================================
-- Beyond Barista Academy - Seed 24-Module Barista Curriculum into Neon
-- Generated by scripts/generate-barista-neon-seed.mjs from
-- src/data/baristaCurriculum.ts - do not hand-edit, regenerate instead.
-- Matches the LIVE Neon schema (integer ids, sort_order, body, minutes).
-- Added alongside the existing 23-course catalog, not replacing it.
-- ====================================================================

DO $$
DECLARE
  v_course_id integer;
  v_mod_ids integer[] := '{}';
  v_mid integer;
BEGIN
  VALUES (
    'professional-barista-mastery-24-module',
    'Professional Barista Mastery & Coffee Ecosystem (24 Modules + Certification)',
    'Advanced',
    '24 weeks',
    'The complete 24-module professional barista program from bean origin to roasting, brewing, sensory skills, hospitality management, and entrepreneurship, plus a final certification exam.',
    '/images/barista.jpg',
    'Free',
    'Coach Egide HATEGEKIMANA',
    500,
    'active',
    to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
  )
  ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description
  RETURNING id INTO v_course_id;

  -- Clear any previous modules for this course (cascades to lessons) so this script is idempotent
  DELETE FROM public.modules WHERE course_id = v_course_id;


END $$;
